ARCHIVE_BASE64 = ''


def inventory(folder):
    result = {}
    for file in sorted(folder.rglob('*')):
        relative = file.relative_to(folder)
        if '__pycache__' in relative.parts or file.name == '.DS_Store' or file.suffix == '.pyc':
            continue
        if file.is_symlink():
            raise ValueError('Symbolic links are not accepted: ' + str(relative))
        if file.is_file():
            result[relative.as_posix()] = hashlib.sha256(file.read_bytes()).hexdigest()
    return result


def payload():
    release = RELEASE
    archive_name = release.get('archive')
    if release.get('name') != NAME or archive_name != NAME + '-0.8.1-trial.zip':
        raise ValueError('Unexpected release identity or archive name')
    archive_data = base64.b64decode(ARCHIVE_BASE64, validate=True)
    if hashlib.sha256(archive_data).hexdigest() != release.get('archive_sha256'):
        raise ValueError('Archive checksum differs from release.json')
    expected = release.get('files')
    if not expected or any(Path(p).is_absolute() or '..' in Path(p).parts for p in expected):
        raise ValueError('Invalid Skill file manifest')
    temporary = tempfile.TemporaryDirectory(prefix='proposal-payload-')
    atexit.register(temporary.cleanup)
    with ZipFile(io.BytesIO(archive_data)) as bundle:
        names = bundle.namelist()
        if len(names) != len(expected) or set(names) != {NAME + '/' + p for p in expected}:
            raise ValueError('Unexpected archive paths')
        bundle.extractall(temporary.name)
    source = Path(temporary.name) / NAME
    if inventory(source) != expected:
        raise ValueError('Skill files differ from release.json; installation stopped')
    if not (source / 'SKILL.md').is_file():
        raise ValueError('SKILL.md is missing')
    return release, source


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    location = parser.add_mutually_exclusive_group()
    location.add_argument('--dest', type=Path, help='Parent skills directory')
    location.add_argument('--project', type=Path, help='Install under PROJECT/.agents/skills')
    parser.add_argument('--update', action='store_true', help='Back up an existing different version before replacing it')
    parser.add_argument('--dry-run', action='store_true', help='Validate and report without writing')
    args = parser.parse_args()
    release, source = payload()
    parent = args.dest or (args.project / '.agents/skills' if args.project else Path.home() / '.agents/skills')
    parent = parent.expanduser().resolve()
    destination = parent / NAME
    if destination.is_symlink():
        raise ValueError('Destination is a symbolic link; choose its intended source explicitly')
    existing = destination.exists()
    if existing and not destination.is_dir():
        raise ValueError('Destination exists and is not a directory')
    same = existing and inventory(destination) == release['files']
    action = 'unchanged' if same else ('update' if existing else 'install')
    result = {'name': NAME, 'version': release['version'], 'destination': str(destination), 'action': action, 'dry_run': args.dry_run}
    if existing and not same and not args.update:
        raise ValueError('A different installation exists. Use --update to preserve a backup and replace it')
    if args.dry_run or same:
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return
    parent.mkdir(parents=True, exist_ok=True)
    backup = None
    with tempfile.TemporaryDirectory(prefix='.proposal-install-', dir=parent.parent) as temporary:
        staged = Path(temporary) / NAME
        shutil.copytree(source, staged, ignore=shutil.ignore_patterns('__pycache__', '*.pyc', '.DS_Store'))
        if inventory(staged) != release['files']:
            raise ValueError('Staged copy failed verification')
        if existing:
            stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
            backup = parent.parent / 'skill-backups' / (NAME + '-' + stamp + '-' + uuid.uuid4().hex[:8])
            backup.parent.mkdir(parents=True, exist_ok=True)
            os.replace(destination, backup)
        try:
            os.replace(staged, destination)
        except OSError:
            if backup and not destination.exists():
                os.replace(backup, destination)
            raise
    result['backup'] = str(backup) if backup else None
    result['next_step'] = 'Use $proposal-producer in the next turn; check document generation tools and CJK rendering in this environment.'
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    try:
        main()
    except (ValueError, KeyError, TypeError, OSError, json.JSONDecodeError) as error:
        print(json.dumps({'error': str(error)}, ensure_ascii=False), file=sys.stderr)
        sys.exit(2)
